UPDATE "Asset" SET "html" = '<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cobalt and Warm Neutral Palette</title>
<style>:root{--canvas:#f7f7f3;--surface:#fff;--ink:#171b2a;--muted:#667085;--line:#deded8;--brand:#3559c7}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:14px/1.5 ui-sans-serif,system-ui,sans-serif}button{font:inherit}.shell{max-width:1100px;margin:auto;padding:32px}header{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:24px}h1{margin:4px 0;font-size:30px;letter-spacing:-.03em}.eyebrow{color:var(--brand);font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}nav{display:flex;gap:6px}.tab,.swatch{border:1px solid var(--line);background:var(--surface);color:inherit;border-radius:8px;cursor:pointer}.tab{padding:8px 12px}.tab[aria-pressed="true"]{border-color:var(--brand);box-shadow:0 0 0 2px #3559c722;color:var(--brand)}.layout{display:grid;grid-template-columns:minmax(0,2fr) minmax(260px,1fr);gap:18px}.swatches{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.swatch{padding:0;text-align:left;overflow:hidden}.swatch:focus-visible{outline:2px solid var(--brand);outline-offset:2px}.swatch[aria-pressed="true"]{border-color:var(--brand);box-shadow:0 0 0 2px #3559c72b}.color{height:112px;background:var(--color)}.meta{display:flex;justify-content:space-between;padding:12px;font-weight:700}.panel{border:1px solid var(--line);border-radius:10px;background:var(--surface);padding:20px;align-self:start;position:sticky;top:20px}.sample{margin-top:18px;padding:16px;border-radius:8px;background:#f7f7f3}.primary{border:0;border-radius:7px;background:var(--brand);color:white;padding:10px 14px;font-weight:700}.badge{display:inline-flex;margin-left:8px;padding:4px 8px;border-radius:999px;background:#e6f3ec;color:#247a55;font-size:12px;font-weight:700}@media(max-width:720px){.shell{padding:20px}.layout{grid-template-columns:1fr}.swatches{grid-template-columns:1fr}.panel{position:static}}</style></head>
<body><main class="shell" data-harness-artifact="asset" data-mock-screen="asset-palette"><header><div><div class="eyebrow">Asset / Color system</div><h1>Cobalt and warm neutrals</h1><p>Choose a token to inspect its role in the interface.</p></div><nav aria-label="Asset sections"><button class="tab" type="button" aria-pressed="true">Colors</button><button class="tab" type="button" aria-pressed="false">Components</button></nav></header><div class="layout"><section class="swatches" aria-label="Color tokens"><button class="swatch" type="button" aria-pressed="true" data-name="Primary" data-value="#3559C7" data-use="Selection, focus, primary action"><span class="color" style="--color:#3559c7"></span><span class="meta"><span>Primary</span><span>#3559C7</span></span></button><button class="swatch" type="button" aria-pressed="false" data-name="Canvas" data-value="#F7F7F3" data-use="Application background"><span class="color" style="--color:#f7f7f3"></span><span class="meta"><span>Canvas</span><span>#F7F7F3</span></span></button><button class="swatch" type="button" aria-pressed="false" data-name="Surface" data-value="#FFFFFF" data-use="Cards and panels"><span class="color" style="--color:#fff"></span><span class="meta"><span>Surface</span><span>#FFFFFF</span></span></button><button class="swatch" type="button" aria-pressed="false" data-name="Ink" data-value="#171B2A" data-use="Primary text"><span class="color" style="--color:#171b2a"></span><span class="meta"><span>Ink</span><span>#171B2A</span></span></button><button class="swatch" type="button" aria-pressed="false" data-name="Muted" data-value="#667085" data-use="Metadata and secondary text"><span class="color" style="--color:#667085"></span><span class="meta"><span>Muted</span><span>#667085</span></span></button><button class="swatch" type="button" aria-pressed="false" data-name="Success" data-value="#247A55" data-use="Connected and complete"><span class="color" style="--color:#247a55"></span><span class="meta"><span>Success</span><span>#247A55</span></span></button><button class="swatch" type="button" aria-pressed="false" data-name="Warning" data-value="#986400" data-use="Stale and attention"><span class="color" style="--color:#986400"></span><span class="meta"><span>Warning</span><span>#986400</span></span></button></section><article class="panel" data-ui="card"><div class="eyebrow">Selected token</div><h2 id="token-name">Primary</h2><p id="token-value">#3559C7</p><p id="token-use">Selection, focus, primary action</p><div class="sample"><button class="primary" type="button">Open artifact</button><span class="badge">Connected</span></div></article></div></main>
<script>document.querySelectorAll(".swatch").forEach(function(button){button.addEventListener("click",function(){document.querySelectorAll(".swatch").forEach(function(item){item.setAttribute("aria-pressed","false")});button.setAttribute("aria-pressed","true");document.getElementById("token-name").textContent=button.dataset.name;document.getElementById("token-value").textContent=button.dataset.value;document.getElementById("token-use").textContent=button.dataset.use})});document.querySelectorAll(".tab").forEach(function(button){button.addEventListener("click",function(){document.querySelectorAll(".tab").forEach(function(item){item.setAttribute("aria-pressed","false")});button.setAttribute("aria-pressed","true")})});</script></body></html>' WHERE "id" = 1 AND "projectId" = 1 AND "title" = 'Cobalt & Warm Neutral Palette';

UPDATE "Asset" SET "html" = '<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Geist Typography Scale</title><style>*{box-sizing:border-box}body{margin:0;background:#f7f7f3;color:#171b2a;font-family:Geist,ui-sans-serif,system-ui,sans-serif}.shell{max-width:1040px;margin:auto;padding:36px}header{display:flex;justify-content:space-between;align-items:end;border-bottom:1px solid #deded8;padding-bottom:22px}h1{font-size:32px;letter-spacing:-.04em;margin:5px 0}.eyebrow{font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:#3559c7;font-weight:800}nav{display:flex;gap:4px;background:#ecece7;padding:4px;border-radius:9px}button{font:inherit;cursor:pointer}.density{border:0;border-radius:6px;background:transparent;padding:8px 11px}.density[aria-pressed="true"]{background:#fff;box-shadow:0 1px 3px #0002}.list{margin-top:20px;border:1px solid #deded8;border-radius:12px;background:#fff;overflow:hidden}.row{display:grid;grid-template-columns:110px minmax(0,1fr) 150px;align-items:center;gap:24px;padding:24px;border-bottom:1px solid #ecece7}.row:last-child{border:0}.compact .row{padding:12px 20px}.role{color:#667085;font-size:12px;font-weight:700;text-transform:uppercase}.specimen{margin:0;line-height:var(--lh);font-size:var(--size);font-weight:var(--weight);letter-spacing:-.025em}.metrics{color:#667085;font:12px/1.5 ui-monospace,monospace}.note{margin-top:18px;padding:18px;border:1px solid #deded8;border-radius:10px;background:#fff}@media(max-width:680px){.shell{padding:20px}header{align-items:start;flex-direction:column;gap:14px}.row{grid-template-columns:1fr;gap:8px}.specimen{font-size:clamp(18px,var(--size),36px)}}</style></head><body><main class="shell" data-harness-artifact="asset" data-mock-screen="asset-typography"><header><div><div class="eyebrow">Asset / Type system</div><h1>Geist typography scale</h1><p>Readable hierarchy for dense artifact workspaces.</p></div><nav aria-label="Typography density"><button class="density" type="button" data-density="comfortable" aria-pressed="true">Comfortable</button><button class="density" type="button" data-density="compact" aria-pressed="false">Compact</button></nav></header><section class="list" id="type-list" aria-label="Typography specimens"><article class="row" data-ui="card"><div class="role">Display</div><p class="specimen" style="--size:48px;--lh:52px;--weight:700">Build with clarity.</p><div class="metrics">48 / 52 · 700</div></article><article class="row" data-ui="card"><div class="role">H1</div><p class="specimen" style="--size:36px;--lh:40px;--weight:700">Project workbench</p><div class="metrics">36 / 40 · 700</div></article><article class="row" data-ui="card"><div class="role">H2</div><p class="specimen" style="--size:24px;--lh:30px;--weight:650">Plan hierarchy</p><div class="metrics">24 / 30 · 650</div></article><article class="row" data-ui="card"><div class="role">Body</div><p class="specimen" style="--size:14px;--lh:24px;--weight:400">Review the artifact content without losing its context.</p><div class="metrics">14 / 24 · 400</div></article><article class="row" data-ui="card"><div class="role">Meta</div><p class="specimen" style="--size:12px;--lh:18px;--weight:550">UPDATED 8 MIN AGO</p><div class="metrics">12 / 18 · 550</div></article><article class="row" data-ui="card"><div class="role">Mono</div><p class="specimen" style="--size:11px;--lh:16px;--weight:500">task_01HXM2T7</p><div class="metrics">11 / 16 · 500</div></article></section><article class="note" data-ui="card"><strong>Font stack</strong><p>Geist, ui-sans-serif, system-ui</p></article></main><script>document.querySelectorAll(".density").forEach(function(button){button.addEventListener("click",function(){document.querySelectorAll(".density").forEach(function(item){item.setAttribute("aria-pressed","false")});button.setAttribute("aria-pressed","true");document.getElementById("type-list").classList.toggle("compact",button.dataset.density==="compact")})});</script></body></html>' WHERE "id" = 2 AND "projectId" = 1 AND "title" = 'Geist Typography Scale';

