ass="filter" type="button" aria-pressed="true">All</button><button class="filter" type="button" aria-pressed="false">Planning</button><button class="filter" type="button" aria-pressed="false">Build</button><button class="filter" type="button" aria-pressed="false">Quality</button></nav><div class="workspace"><section class="gallery" aria-label="Artifact code gallery"><button class="code" type="button" aria-pressed="true" data-code="OV" data-name="Overview" data-place="Project summary"><span class="badge">OV</span><span>Overview</span></button><button class="code" type="button" aria-pressed="false" data-code="PL" data-name="Plan" data-place="Project root"><span class="badge">PL</span><span>Plan</span></button><button class="code" type="button" aria-pressed="false" data-code="TK" data-name="Task" data-place="Inside a plan"><span class="badge">TK</span><span>Task</span></button><button class="code" type="button" aria-pressed="false" data-code="DR" data-name="Draft" data-place="Project root"><span class="badge">DR</span><span>Draft</span></button><button class="code" type="button" aria-pressed="false" data-code="AR" data-name="Architecture" data-place="Project root"><span class="badge">AR</span><span>Architecture</span></button><button class="code" type="button" aria-pressed="false" data-code="WF" data-name="Wireframe" data-place="Plan and task"><span class="badge">WF</span><span>Wireframe</span></button><button class="code" type="button" aria-pressed="false" data-code="AS" data-name="Asset" data-place="Plan and task"><span class="badge">AS</span><span>Asset</span></button><button class="code" type="button" aria-pressed="false" data-code="DS" data-name="Design" data-place="Plan and task"><span class="badge">DS</span><span>Design</span></button><button class="code" type="button" aria-pressed="false" data-code="RV" data-name="Review" data-place="Plan output"><span class="badge">RV</span><span>Review</span></button></section><article class="detail" data-ui="card"><div class="eyebrow">Selected code</div><h2><span id="detail-code">OV</span> · <span id="detail-name">Overview</span></h2><p id="detail-place">Project summary</p><p>Used wherever an artifact needs a quick, scannable identity.</p></article></div><section class="relation" aria-label="Artifact relationship"><h2>Relationship</h2><div class="flow"><span class="node">Plan</span><span class="arrow">→</span><span class="node">Task</span><span class="arrow">→</span><span class="node">Wireframe / Asset / Design</span><span class="arrow">→</span><span class="node">Review</span></div></section></main><script>document.querySelectorAll(".code").forEach(function(button){button.addEventListener("click",function(){document.querySelectorAll(".code").forEach(function(item){item.setAttribute("aria-pressed","false")});button.setAttribute("aria-pressed","true");document.getElementById("detail-code").textContent=button.dataset.code;document.getElementById("detail-name").textContent=button.dataset.name;document.getElementById("detail-place").textContent=button.dataset.place})});document.querySelectorAll(".filter").forEach(function(button){button.addEventListener("click",function(){document.querySelectorAll(".filter").forEach(function(item){item.setAttribute("aria-pressed","false")});button.setAttribute("aria-pressed","true")})});</script></body></html>' WHERE "id" = 3 AND "projectId" = 1 AND "title" = 'Artifact Type Codes';

UPDATE "Asset" SET "html" = '<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard QA Viewports</title><style>*{box-sizing:border-box}body{margin:0;background:#f1f1ed;color:#171b2a;font:14px/1.5 system-ui,sans-serif}.shell{max-width:1120px;margin:auto;padding:30px}header{display:flex;justify-content:space-between;gap:18px;align-items:end}.eyebrow{font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:#3559c7}h1{font-size:30px;margin:4px 0}nav{display:flex;gap:6px;flex-wrap:wrap}.viewport{border:1px solid #d3d3cc;border-radius:8px;background:#fff;padding:9px 12px;font:inherit;cursor:pointer}.viewport[aria-pressed="true"]{border-color:#3559c7;color:#3559c7;box-shadow:0 0 0 2px #3559c722}.stage{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:18px;margin-top:22px}.canvas{display:grid;place-items:center;min-height:520px;padding:30px;border:1px solid #d3d3cc;border-radius:12px;background:#deded8}.frame{width:min(100%,720px);aspect-ratio:var(--ratio);max-height:460px;border:6px solid #25282f;border-radius:10px;background:#fff;overflow:hidden;display:grid;grid-template-columns:22% 1fr}.mini-side{background:#f4f4f0;border-right:1px solid #ddd;padding:4%}.mini-line{height:7px;margin:8px 0;border-radius:4px;background:#d4d5d8}.mini-main{padding:4%}.mini-head{display:flex;justify-content:space-between;border-bottom:1px solid #ddd;padding-bottom:3%}.mini-tabs{display:flex;gap:3%;margin:4% 0}.mini-tab{height:8px;width:16%;border-radius:4px;background:#3559c7}.mini-grid{display:grid;grid-template-columns:1fr 1.5fr;gap:4%}.mini-card{height:130px;border:1px solid #ddd;border-radius:5px}.checks{border:1px solid #d3d3cc;border-radius:12px;background:#fff;padding:20px;align-self:start}.checks ul{padding-left:20px}.pass{color:#247a55;font-weight:750}@media(max-width:760px){.shell{padding:18px}header{align-items:start;flex-direction:column}.stage{grid-template-columns:1fr}.canvas{min-height:430px;padding:16px}.frame[data-mobile="true"]{max-width:240px;grid-template-columns:1fr}.frame[data-mobile="true"] .mini-side{display:none}.mini-grid{grid-template-columns:1fr}}</style></head><body><main class="shell" data-harness-artifact="asset" data-mock-screen="asset-viewports"><header><div><div class="eyebrow">Asset / QA</div><h1>Responsive viewport matrix</h1><p id="viewport-note">Wide desktop · persistent project navigation.</p></div><nav aria-label="Preview viewport"><button class="viewport" type="button" aria-pressed="true" data-ratio="16 / 10" data-mobile="false" data-note="Wide desktop · persistent project navigation.">1440 × 900</button><button class="viewport" type="button" aria-pressed="false" data-ratio="16 / 9" data-mobile="false" data-note="Compact desktop · balanced list and detail.">1280 × 720</button><button class="viewport" type="button" aria-pressed="false" data-ratio="390 / 844" data-mobile="true" data-note="Mobile · drawer navigation and full-screen detail.">390 × 844</button></nav></header><section class="stage"><div class="canvas"><div class="frame" id="frame" data-mobile="false" style="--ratio:16 / 10"><aside class="mini-side"><div class="mini-line"></div><div class="mini-line"></div><div class="mini-line"></div><div class="mini-line"></div></aside><div class="mini-main"><div class="mini-head"><div class="mini-line" style="width:35%"></div><div class="mini-line" style="width:18%"></div></div><div class="mini-tabs"><span class="mini-tab"></span><span class="mini-line" style="width:16%"></span><span class="mini-line" style="width:16%"></span></div><div class="mini-grid"><div class="mini-card"></div><div class="mini-card"></div></div></div></div></div><article class="checks" data-ui="card"><div class="eyebrow">Acceptance checks</div><h2>Current frame</h2><ul><li><span class="pass">Pass</span> · no horizontal overflow</li><li><span class="pass">Pass</span> · 44px touch target</li><li><span class="pass">Pass</span> · 2px cobalt focus</li><li><span class="pass">Pass</span> · readable content order</li></ul></article></section></main><script>document.querySelectorAll(".viewport").forEach(function(button){button.addEventListener("click",function(){document.querySelectorAll(".viewport").forEach(function(item){item.setAttribute("aria-pressed","false")});button.setAttribute("aria-pressed","true");var frame=document.getElementById("frame");frame.style.setProperty("--ratio",button.dataset.ratio);frame.dataset.mobile=button.dataset.mobile;document.getElementById("viewport-note").textContent=button.dataset.note})});</script></body></html>' WHERE "id" = 4 AND "projectId" = 1 AND "title" = 'Dashboard QA Viewports';

UPDATE "Asset" SET "html" = '<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Remote Status Tokens</title><style>:root{--success:#247a55;--info:#3559c7;--warning:#986400;--danger:#b33a3a;--neutral:#667085}*{box-sizing:border-box}body{margin:0;background:#f7f7f3;color:#171b2a;font:14px/1.5 system-ui,sans-serif}.shell{max-width:1080px;margin:auto;padding:34px}.eyebrow{color:#3559c7;font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}h1{font-size:32px;margin:4px 0}nav{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:22px 0}.status{border:1px solid #deded8;border-radius:10px;background:#fff;padding:15px;text-align:left;font:inherit;cursor:pointer}.status[aria-pressed="true"]{border-color:var(--tone);box-shadow:0 0 0 2px color-mix(in srgb,var(--tone) 20%,transparent)}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--tone);margin-right:7px}.status small{display:block;color:#667085;margin-top:7px}.specimen{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(260px,1fr);gap:18px}.repo,.tokens{border:1px solid #deded8;border-radius:12px;background:#fff;padding:22px}.repo-head{display:flex;justify-content:space-between;gap:16px}.pill{display:inline-flex;align-items:center;border-radius:999px;padding:6px 10px;background:#edf6f1;color:var(--success);font-size:12px;font-weight:800}.bar{height:8px;border-radius:99px;background:#ecece7;overflow:hidden;margin:22px 0}.fill{height:100%;width:100%;background:var(--success);transition:width .3s}.action{border:0;border-radius:8px;background:#171b2a;color:#fff;padding:10px 14px;font:inherit;font-weight:700}.token-row{display:flex;justify-content:space-between;border-bottom:1px solid #ecece7;padding:10px 0}@media(max-width:760px){.shell{padding:20px}nav{grid-template-columns:1fr 1fr}.specimen{grid-template-columns:1fr}}</style></head><body><main class="shell" data-harness-artifact="asset" data-mock-screen="asset-remote-status"><header><div class="eyebrow">Asset / Remote state</div><h1>Remote status tokens</h1><p>Status is always communicated by color, label and supporting text.</p></header><nav aria-label="Remote status specimens"><button class="status" type="button" aria-pressed="true" style="--tone:#247a55" data-name="Connected" data-copy="Up to date · synced moments ago" data-width="100%" data-color="#247a55"><span class="dot"></span><strong>Connected</strong><small>Healthy</small></button><button class="status" type="button" aria-pressed="false" style="--tone:#3559c7" data-name="Syncing" data-copy="Fetching remote changes" data-width="58%" data-color="#3559c7"><span class="dot"></span><strong>Syncing</strong><small>In progress</small></button><button class="status" type="button" aria-pressed="false" style="--tone:#986400" data-name="Stale" data-copy="Last sync was 2 hours ago" data-width="34%" data-color="#986400"><span class="dot"></span><strong>Stale</strong><small>Attention</small></button><button class="status" type="button" aria-pressed="false" style="--tone:#b33a3a" data-name="Failed" data-copy="Authentication must be renewed" data-width="12%" data-color="#b33a3a"><span class="dot"></span><strong>Failed</strong><small>Action needed</small></button><button class="status" type="button" aria-pressed="false" style="--tone:#667085" data-name="Offline" data-copy="Remote source is unavailable" data-width="0%" data-color="#667085"><span class="dot"></span><strong>Offline</strong><small>Unavailable</small></button></nav><section class="specimen"><article class="repo" data-ui="card"><div class="repo-head"><div><div class="eyebrow">Repository specimen</div><h2>remote-agent-commerce</h2><p>github.com/yusung/remote-agent-commerce</p></div><span class="pill" id="pill"><span class="dot" id="pill-dot"></span><span id="state-name">Connected</span></span></div><div class="bar"><div class="fill" id="progress"></div></div><p id="state-copy">Up to date · synced moments ago</p><button class="action" type="button" id="sync">Sync now</button></article><article class="tokens" data-ui="card"><div class="eyebrow">Token anatomy</div><h2>Three signals</h2><div class="token-row"><span>Color</span><strong id="token-color">#247A55</strong></div><div class="token-row"><span>Label</span><strong>Always visible</strong></div><div class="token-row"><span>Context</span><strong>Time or action</strong></div></article></section></main><script>document.querySelectorAll(".status").forEach(function(button){button.addEventListener("click",function(){document.querySelectorAll(".status").forEach(function(item){item.setAttribute("aria-pressed","false")});button.setAttribute("aria-pressed","true");var color=button.dataset.color;var pill=document.getElementById("pill");pill.style.color=color;pill.style.background=color+"18";document.getElementById("pill-dot").style.background=color;document.getElementById("state-name").textContent=button.dataset.name;document.getElementById("state-copy").textContent=button.dataset.copy;document.getElementById("progress").style.width=button.dataset.width;document.getElementById("progress").style.background=color;document.getElementById("token-color").textContent=color.toUpperCase()})});document.getElementById("sync").addEventListener("click",function(){document.getElementById("state-name").textContent="Syncing";document.getElementById("state-copy").textContent="Fetching remote changes";document.getElementById("progress").style.width="58%"});</script></body></html>' WHERE "id" = 5 AND "projectId" = 2 AND "title" = 'Remote Status Tokens';

