ck",function(){document.querySelectorAll(".record").forEach(function(item){item.setAttribute("aria-pressed","false")});button.setAttribute("aria-pressed","true");document.getElementById("detail-title").textContent=button.dataset.title;document.getElementById("detail-status").textContent=button.dataset.status;document.getElementById("detail-copy").textContent=button.dataset.copy})});</script></body></html>' WHERE "id" = 1 AND "projectId" = 1 AND "title" = 'Desktop Overview Workbench';

