})});document.querySelectorAll(".output").forEach(function(button){button.addEventListener("click",function(){document.getElementById("preview-title").textContent=button.dataset.output;document.getElementById("preview").classList.add("open")})});function closePreview(){document.getElementById("preview").classList.remove("open")}document.getElementById("close").addEventListener("click",closePreview);document.addEventListener("keydown",function(event){if(event.key==="Escape")closePreview()});</script></body></html>' WHERE "id" = 2 AND "projectId" = 1 AND "title" = 'Artifact Detail Panel';

